-- PT107-S4-Q10. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT107-S4-Q10$batch09$ AND q.stimulus=$batch09$Parents should not necessarily raise their children in the ways experts recommend, even if some of those experts are themselves parents. After all, parents are the ones who directly experience which methods are successful in raising their own children.$batch09$ AND q.prompt=$batch09$Which one of the following most closely conforms to the principle that the passage above illustrates?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT107-S4-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT107-S4-Q10$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S4-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT107-S4-Q10$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Parents shouldn't necessarily raise their children the way experts recommend.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Parents directly experience which methods work with their own children.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The principle: someone with direct experience of the particular case may do better to set aside the advice of general experts. Notice the soft wording. Parents "should not necessarily" follow the experts. The author isn't saying experts are always wrong.$batch09$), (3, $batch09$Goal$batch09$, $batch09$A person with firsthand knowledge of a specific case who might do well to ignore experts who lack that knowledge.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT107-S4-Q10$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Theory fails here because good music is a matter of taste. The stimulus never says parenting is a matter of taste. It says parents know their own children firsthand.$batch09$), ($batch09$B$batch09$, $batch09$The experts are dismissed because they don't care about what matters to ordinary buyers. Our experts are set aside because they lack direct experience of this particular child, not because they don't care.$batch09$), ($batch09$C$batch09$, $batch09$The climber knows this particular mountain, and the experts don't. "Might do well to ignore" matches "should not necessarily" follow. Firsthand knowledge of the specific case beats general expertise.$batch09$), ($batch09$D$batch09$, $batch09$This sides with the expert over the person who works the land.$batch09$), ($batch09$E$batch09$, $batch09$This is the trap, picked by 9%. It does favor your own voice over outside advice. But the reason is that conscience "speaks with a single voice." That's about consistency, not firsthand experience. E also says it is "better to follow" conscience, which is stronger than the stimulus's "not necessarily."$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT107-S4-Q10$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
